using System.Xml.Serialization;
namespace Clc.Polaris.Api.UnitTests.Models { [TestClass] [UnitTest] public sealed class ILLRequestCreateDataXmlSerializationTests { [TestMethod] public void Serialize_IncludesDocumentedFields() { var data=new ILLRequestCreateData{PatronID=1,Title="T",PickupOrgID=2,Author="A"}; using var writer=new StringWriter(); new XmlSerializer(typeof(ILLRequestCreateData)).Serialize(writer,data); var xml=writer.ToString(); Assert.Contains("<PatronID>1</PatronID>",xml); Assert.Contains("<Title>T</Title>",xml); Assert.Contains("<PickupOrgID>2</PickupOrgID>",xml); Assert.Contains("<Author>A</Author>",xml); } } }
